namespace Pathway.Content;

static partial class Curriculum
{
    // Instruction and fully worked models precede practice; module assessments live in AssessmentCatalog.
    private static Lesson[] BuildAlgebraOneLessons()
    {
        // Local stamp avoids static initialization order pitfalls in partial classes.
        var docs = new VersionStamp("Algebra I", "Expressions · equations · functions · models", "2026-10-28", "https://openstax.org/details/books/elementary-algebra-2e");
        var lessons = new Lesson[]
        {
            new("algebra1-meaning-of-expressions", "Algebra language", 1, "From words to algebraic expressions", "A $9 startup fee plus $4 per ticket becomes C = 9 + 4t, where t is ticket count and C is dollars.", "A variable stands for a quantity; a coefficient multiplies it; constants stay fixed.", "## What it means\nA variable stands for a quantity; a coefficient multiplies it; constants stay fixed.\n\n## Where you'll use it\nA $9 startup fee plus $4 per ticket becomes C = 9 + 4t, where t is ticket count and C is dollars. Different t values yield different costs.\n\n## Work through an example\n1. Let b represent bags purchased. 2. Each bag costs $6, so 6b describes the variable part. 3. Add a fixed $5 delivery fee: total = 6b + 5. Check b=2 gives $17.\n\n## Read the math\n6b + 5, b = bags, total in dollars\n\n## Check the reasoning\nAn expression has no equals sign; an equation claims that two expressions have equal value.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "6b + 5, b = bags, total in dollars", new Exercise(ExerciseKind.Numeric, "Practice: From words to algebraic expressions", "A service costs $8 upfront and $3 per unit. Find the total for 5 units.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 23d, Tolerance: 0.001d, Unit: "USD", WorkedSolution: "Five units at $3 each cost 5 × $3 = $15. Add the one-time $8 fee: 8 + 3×5 = 8 + 15 = $23."), null, docs),
            new("algebra1-like-terms", "Algebra language", 2, "Terms and equivalent expressions", "In a scoring system, 4 points per round plus 6 per round gives 10 per round, while a fixed 3-point reward stays separate.", "Like terms share the same variables raised to the same powers and can be combined.", "## What it means\nLike terms share the same variables raised to the same powers and can be combined.\n\n## Where you'll use it\nIn a scoring system, 4 points per round plus 6 per round gives 10 per round, while a fixed 3-point reward stays separate.\n\n## Work through an example\n1. Simplify 3x + 8 − x + 2. 2. Combine x terms: 3x − x = 2x. 3. Add constants: 8 + 2 = 10. Final result 2x + 10. Check with x=4: both are 18.\n\n## Read the math\n3x + 8 − x + 2 = 2x + 10\n\n## Check the reasoning\n2x and 2x² are unlike terms: their variable powers differ.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "3x + 8 − x + 2 = 2x + 10", new Exercise(ExerciseKind.Numeric, "Practice: Terms and equivalent expressions", "Simplify 2x + 7x + 6 at x=2. What number does it evaluate to?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 24d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Combine like terms first: 2x + 7x + 6 = 9x + 6. Replace x with 2: 9×2 + 6 = 18 + 6 = 24."), null, docs),
            new("algebra1-distribution-properties", "Algebra language", 3, "Distributive, associative, and commutative properties", "Buying four lunch combos with a $7 meal and $2 drink costs 4(7+2)=4×7+4×2.", "The distributive property multiplies every term in a group; ordering and grouping rules preserve equivalent values.", "## What it means\nThe distributive property multiplies every term in a group; ordering and grouping rules preserve equivalent values.\n\n## Where you'll use it\nBuying four lunch combos with a $7 meal and $2 drink costs 4(7+2)=4×7+4×2. Distribution and factoring describe the same price two ways.\n\n## Work through an example\n1. Expand 3(2x − 5) using 3×2x + 3×(−5). 2. Obtain 6x − 15. 3. At x=4, compare 3(8−5) = 9 and 24−15=9.\n\n## Read the math\n3(2x − 5) = 6x − 15\n\n## Check the reasoning\nDo not forget to distribute a negative sign: −(x − 2) = −x + 2.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "3(2x − 5) = 6x − 15", new Exercise(ExerciseKind.Numeric, "Practice: Distributive, associative, and commutative properties", "Evaluate 2(3x + 4) at x=2.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 20d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Distribute or substitute: 2(3×2 + 4) = 2(6+4) = 2×10 = 20."), null, docs),
            new("algebra1-multistep-equations", "Equations", 4, "Solve equations with several operations", "A subscription costs a $12 one-time setup plus $5 each month; if its bill is $47, let m be months and solve 12 + 5m = 47.", "Solve by undoing operations on both sides while maintaining equality.", "## What it means\nSolve by undoing operations on both sides while maintaining equality.\n\n## Where you'll use it\nA subscription costs a $12 one-time setup plus $5 each month; if its bill is $47, let m be months and solve 12 + 5m = 47.\n\n## Work through an example\n1. Start with 4(x+2)−3=25. 2. Distribute: 4x+8−3=25. 3. Combine: 4x+5=25. 4. Subtract 5: 4x=20. Divide by 4: x=5. 5. Substitute into the original to confirm 25.\n\n## Read the math\n4(x+2) − 3 = 25 ⇒ x = 5\n\n## Check the reasoning\nAlways check against the original equation, not just a simplified intermediate step.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "4(x+2) − 3 = 25 ⇒ x = 5", new Exercise(ExerciseKind.Numeric, "Practice: Solve equations with several operations", "A ride service costs $6 initially and $4 per mile. For a $38 fare, how many miles?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 8d, Tolerance: 0.001d, Unit: "miles", WorkedSolution: "Let m be miles. Write 6 + 4m = 38. Subtract 6 from both sides: 4m = 32. Divide by 4: m = 8 miles. Check: 6 + 4×8 = 38."), null, docs),
            new("algebra1-both-sides-equations", "Equations", 5, "Variables on both sides and special cases", "Two internet plans cost 5+3m and 17+m dollars after m months.", "Collect variable terms on one side; some equations have no solution or infinitely many.", "## What it means\nCollect variable terms on one side; some equations have no solution or infinitely many.\n\n## Where you'll use it\nTwo internet plans cost 5+3m and 17+m dollars after m months. Their equal-cost month is found by setting the expressions equal.\n\n## Work through an example\n1. Solve 5x−4=2x+11. 2. Subtract 2x from both sides: 3x−4=11. 3. Add 4: 3x=15. 4. Divide: x=5. 5. Check 25−4=21 and 10+11=21.\n\n## Read the math\n5x − 4 = 2x + 11 ⇒ 3x = 15 ⇒ x=5\n\n## Check the reasoning\nIf all variables cancel, 3=5 means no solution; 3=3 means every allowed value works.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "5x − 4 = 2x + 11 ⇒ 3x = 15 ⇒ x=5", new Exercise(ExerciseKind.Numeric, "Practice: Variables on both sides and special cases", "Solve 7x − 8 = 3x + 12.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 5d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Start with 7x−8 = 3x+12. Subtract 3x: 4x−8=12. Add 8: 4x=20. Divide by 4: x=5. Both sides then equal 27."), null, docs),
            new("algebra1-rearrange-formulas", "Equations", 6, "Rearrange formulas for the quantity you need", "The relation distance = rate × time can be rearranged as time = distance ÷ rate.", "A formula is an equation connecting quantities; inverse operations isolate whichever variable you need.", "## What it means\nA formula is an equation connecting quantities; inverse operations isolate whichever variable you need.\n\n## Where you'll use it\nThe relation distance = rate × time can be rearranged as time = distance ÷ rate. It works with compatible units: km ÷ km/h = h.\n\n## Work through an example\n1. Begin with A = lw, where A is area, l length, and w width. 2. Divide both sides by nonzero l to isolate w. 3. Obtain w=A/l. For A=48 m² and l=6 m, w=8 m.\n\n## Read the math\nA = lw ⇒ w = A/l ; 48/6=8 m\n\n## Check the reasoning\nNever divide by a variable without noting the case when it could be zero.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "A = lw ⇒ w = A/l ; 48/6=8 m", new Exercise(ExerciseKind.Numeric, "Practice: Rearrange formulas for the quantity you need", "A rectangle has area 84 m² and length 12 m. Find its width.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 7d, Tolerance: 0.001d, Unit: "m", WorkedSolution: "Area = length × width, so 84 = 12w. Divide by nonzero 12: w = 84/12 = 7 m. Check 12 m × 7 m = 84 m²."), null, docs),
            new("algebra1-inequality-operations", "Inequalities", 7, "Solve inequalities including negative coefficients", "A spending limit uses ≤; a minimum age uses ≥.", "An inequality describes a set of values. Multiplying or dividing by a negative reverses its comparison.", "## What it means\nAn inequality describes a set of values. Multiplying or dividing by a negative reverses its comparison.\n\n## Where you'll use it\nA spending limit uses ≤; a minimum age uses ≥. An answer can be a range rather than one point.\n\n## Work through an example\n1. Solve −3x+4<16. 2. Subtract 4: −3x<12. 3. Divide by −3 and reverse <: x>−4. 4. Check x=0 works (4<16); x=−5 does not (19<16 is false).\n\n## Read the math\n−3x+4<16 ⇒ x>−4\n\n## Check the reasoning\nReversing an inequality sign is necessary only when multiplying or dividing by a negative, not when adding one.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "−3x+4<16 ⇒ x>−4", new Exercise(ExerciseKind.Numeric, "Practice: Solve inequalities including negative coefficients", "Find the boundary of −2x + 6 ≥ 14 (solve equality for the boundary).", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -4d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "The boundary makes −2x+6 = 14. Subtract 6: −2x=8. Divide by −2: x=−4. For the full inequality, −2x+6 ≥ 14, reversing the sign gives x ≤ −4."), null, docs),
            new("algebra1-compound-inequalities", "Inequalities", 8, "Compound inequalities and interval meaning", "A storage temperature requirement 2°C ≤ T ≤ 8°C means between 2 and 8 inclusive.", "An AND inequality requires both constraints; an OR inequality allows either branch.", "## What it means\nAn AND inequality requires both constraints; an OR inequality allows either branch.\n\n## Where you'll use it\nA storage temperature requirement 2°C ≤ T ≤ 8°C means between 2 and 8 inclusive. An unsafe temperature may be T<2 OR T>8.\n\n## Work through an example\n1. Solve 1 < 2x+3 ≤ 11. 2. Subtract 3 everywhere: −2<2x≤8. 3. Divide all three pieces by positive 2: −1<x≤4. 4. Zero satisfies both boundaries; five fails.\n\n## Read the math\n1<2x+3≤11 ⇒ −1<x≤4\n\n## Check the reasoning\nAND means intersection, not union. Endpoint dots are filled for ≤ or ≥, open for < or >.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "1<2x+3≤11 ⇒ −1<x≤4", new Exercise(ExerciseKind.Numeric, "Practice: Compound inequalities and interval meaning", "For 2 ≤ x + 5 ≤ 9, what is the lower endpoint of x?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Subtract 5 from every part of 2 ≤ x+5 ≤ 9: 2−5 ≤ x ≤ 9−5, so −3 ≤ x ≤ 4. The lower endpoint is −3."), null, docs),
            new("algebra1-inequality-word-models", "Inequalities", 9, "Build and interpret constraints", "A theater with 80 seats and 12 already reserved can accept at most 68 additional people, not 68.5.", "Translate a realistic limit into an inequality and interpret whole-number requirements.", "## What it means\nTranslate a realistic limit into an inequality and interpret whole-number requirements.\n\n## Where you'll use it\nA theater with 80 seats and 12 already reserved can accept at most 68 additional people, not 68.5.\n\n## Work through an example\n1. A venue charges $10 admission plus $7 per ride. With $45, write 10+7r≤45. 2. Subtract 10: 7r≤35. 3. Divide: r≤5. 4. Because r counts rides, the maximum is 5 whole rides.\n\n## Read the math\n10 + 7r ≤ 45 ⇒ r ≤ 5\n\n## Check the reasoning\nCheck whether the unknown may be fractional; people, chairs, and tickets must be whole counts.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "10 + 7r ≤ 45 ⇒ r ≤ 5", new Exercise(ExerciseKind.Numeric, "Practice: Build and interpret constraints", "You have $50 for a $14 entry fee and $6 rides. What is the maximum whole number of rides?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 6d, Tolerance: 0.001d, Unit: "rides", WorkedSolution: "Let r be the number of whole rides. 14 + 6r ≤ 50. Subtract 14: 6r ≤ 36. Divide by 6: r ≤ 6. Six rides cost $50 exactly."), null, docs),
            new("algebra1-slope-from-points", "Linear graphs", 10, "Slope as rate of change", "On a graph of miles (y) against hours (x), slope is miles/hour; a negative slope for a tank's level means liquid is draining.", "Slope m = (y₂−y₁)/(x₂−x₁) measures vertical change per horizontal change.", "## What it means\nSlope m = (y₂−y₁)/(x₂−x₁) measures vertical change per horizontal change.\n\n## Where you'll use it\nOn a graph of miles (y) against hours (x), slope is miles/hour; a negative slope for a tank's level means liquid is draining.\n\n## Work through an example\n1. Take points (1,7) and (3,3). 2. Change in y: 3−7=−4. 3. Change in x: 3−1=2. 4. Slope = −4/2 = −2. The line falls 2 units for each unit right.\n\n## Read the math\nm=(3−7)/(3−1)=−2\n\n## Check the reasoning\nVertical lines have zero run and undefined slope. Do not reverse numerator and denominator.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "m=(3−7)/(3−1)=−2", new Exercise(ExerciseKind.Numeric, "Practice: Slope as rate of change", "A line passes through (0,5) and (2,−1). Find the slope.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -3d, Tolerance: 0.001d, Unit: "units/unit", WorkedSolution: "For (0,5) and (2,−1), vertical change = −1−5 = −6. Horizontal change = 2−0 = 2. Slope m = −6/2 = −3 units of y per unit of x."), null, docs),
            new("algebra1-slope-intercept", "Linear graphs", 11, "Graph lines with slope and intercept", "A courier charges $8 dispatch plus $2 per kilometer: C = 2d+8.", "A line can be described by y = mx + b, where m is the slope and b is the y-intercept.", "## What it means\nA line can be described by y = mx + b, where m is the slope and b is the y-intercept.\n\n## Where you'll use it\nA courier charges $8 dispatch plus $2 per kilometer: C = 2d+8. At d=0, the charge is $8; each additional kilometer adds $2.\n\n## Work through an example\n1. Given y=−2x+5, start at the y-intercept (0,5). 2. Slope −2 moves down 2 for each step right: (1,3), (2,1). 3. Draw a line through the points. 4. For x=4, y=−8+5=−3.\n\n## Read the math\ny = −2x + 5 ; (0,5), (1,3), (2,1)\n\n## Check the reasoning\nA line with b≠0 is not proportional even if its slope stays constant; proportional lines go through the origin.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "y = −2x + 5 ; (0,5), (1,3), (2,1)", new Exercise(ExerciseKind.Numeric, "Practice: Graph lines with slope and intercept", "Evaluate y = −2x + 5 when x = 4.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Use y = −2x + 5 and x = 4. Multiply −2×4=−8. Add 5: y=−3."), null, docs),
            new("algebra1-parallel-perpendicular", "Linear graphs", 12, "Parallel and perpendicular lines", "Roads built parallel keep the same direction; perpendicular streets meet at a right angle.", "Parallel nonvertical lines share slope; perpendicular nonvertical lines have negative reciprocal slopes.", "## What it means\nParallel nonvertical lines share slope; perpendicular nonvertical lines have negative reciprocal slopes.\n\n## Where you'll use it\nRoads built parallel keep the same direction; perpendicular streets meet at a right angle. For m=2, a perpendicular slope is −1/2.\n\n## Work through an example\n1. A road follows y=3x+1, so m=3. 2. Any parallel line has m=3. 3. A perpendicular line has m=−1/3 (because 3×−1/3=−1). 4. A line through (0,4) parallel to the original is y=3x+4.\n\n## Read the math\nparallel m=3 ; perpendicular m=−1/3\n\n## Check the reasoning\nVertical and horizontal lines are also perpendicular; their slopes require separate handling because vertical slope is undefined.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "parallel m=3 ; perpendicular m=−1/3", new Exercise(ExerciseKind.Numeric, "Practice: Parallel and perpendicular lines", "A line has slope 2. What is the slope of a perpendicular line?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -0.5d, Tolerance: 0.001d, Unit: "units/unit", WorkedSolution: "Perpendicular nonvertical slopes multiply to −1. For original m=2, solve 2×m_new = −1, so m_new = −1/2 = −0.5."), null, docs),
            new("algebra1-systems-graphing", "Systems", 13, "Systems and intersection points", "Two payment plans might cost the same at one number of months.", "A system is a collection of equations to satisfy simultaneously; a solution is their common point.", "## What it means\nA system is a collection of equations to satisfy simultaneously; a solution is their common point.\n\n## Where you'll use it\nTwo payment plans might cost the same at one number of months. Where their lines intersect gives that break-even point.\n\n## Work through an example\n1. Compare y=x+2 and y=−x+6. 2. Set equal: x+2=−x+6. 3. Add x: 2x+2=6. Subtract 2 and divide: x=2. 4. y=2+2=4, so intersection is (2,4).\n\n## Read the math\ny=x+2 and y=−x+6 meet at (2,4)\n\n## Check the reasoning\nParallel distinct lines never intersect (no solution); identical lines share infinitely many solutions.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "y=x+2 and y=−x+6 meet at (2,4)", new Exercise(ExerciseKind.Numeric, "Practice: Systems and intersection points", "For y=x+2 and y=−x+6, what is the y-coordinate at the intersection?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 4d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "At intersection, x+2=−x+6. Add x and subtract 2: 2x=4, so x=2. Substitute into y=x+2: y=4."), null, docs),
            new("algebra1-systems-substitution", "Systems", 14, "Solve systems by substitution", "If one box has x pens and the other has x+3 pens, a total of 13 pens creates x+(x+3)=13.", "Substitution replaces a variable with an equivalent expression from another equation.", "## What it means\nSubstitution replaces a variable with an equivalent expression from another equation.\n\n## Where you'll use it\nIf one box has x pens and the other has x+3 pens, a total of 13 pens creates x+(x+3)=13.\n\n## Work through an example\n1. Solve y=2x+1 and x+y=10. 2. Replace y in the second equation: x+(2x+1)=10. 3. Combine 3x+1=10, so x=3. 4. Then y=7. Check 3+7=10 and 2×3+1=7.\n\n## Read the math\ny=2x+1 ; x+y=10 ⇒ x=3,y=7\n\n## Check the reasoning\nSubstitute into the *other* equation to make progress; simply rewriting y=2x+1 in itself tells you nothing.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "y=2x+1 ; x+y=10 ⇒ x=3,y=7", new Exercise(ExerciseKind.Numeric, "Practice: Solve systems by substitution", "For y=2x+1 and x+y=10, find x.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Substitute y=2x+1 into x+y=10: x+2x+1=10. Combine 3x+1=10, so 3x=9 and x=3. Check y=7 and 3+7=10."), null, docs),
            new("algebra1-systems-elimination", "Systems", 15, "Solve systems by elimination", "Tickets for adults and children have different prices.", "Adding or subtracting aligned equations can eliminate one unknown.", "## What it means\nAdding or subtracting aligned equations can eliminate one unknown.\n\n## Where you'll use it\nTickets for adults and children have different prices. Knowing total tickets and total revenue gives a system to solve their counts.\n\n## Work through an example\n1. Solve 2x+y=13 and 2x−y=3. 2. Add equations: 4x=16, giving x=4. 3. Substitute x=4 into 2x+y=13: y=5. 4. Verify 8+5=13 and 8−5=3.\n\n## Read the math\n2x+y=13 ; 2x−y=3 ⇒ 4x=16 ⇒ x=4\n\n## Check the reasoning\nIf coefficients are not opposite, multiply one or both *entire equations* to align them before eliminating.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "2x+y=13 ; 2x−y=3 ⇒ 4x=16 ⇒ x=4", new Exercise(ExerciseKind.Numeric, "Practice: Solve systems by elimination", "Solve 3x+y=17 and 3x−y=7 for x.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 4d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Add 3x+y=17 and 3x−y=7. The y terms cancel, leaving 6x=24. Divide by 6 to obtain x=4."), null, docs),
            new("algebra1-exponent-rules", "Exponents and growth", 16, "Exponent rules with positive and negative powers", "A computer address space doubles for each new binary bit: 2⁵ × 2³ = 2⁸ = 256 possibilities.", "For the same nonzero base, multiplying powers adds exponents and dividing powers subtracts exponents.", "## What it means\nFor the same nonzero base, multiplying powers adds exponents and dividing powers subtracts exponents.\n\n## Where you'll use it\nA computer address space doubles for each new binary bit: 2⁵ × 2³ = 2⁸ = 256 possibilities.\n\n## Work through an example\n1. Simplify (x³ × x²) / x⁴ for x≠0. 2. Add exponents in multiplication: x⁵/x⁴. 3. Subtract powers when dividing: x¹=x. 4. For x=3, both expressions equal 3.\n\n## Read the math\nx³ × x² / x⁴ = x\n\n## Check the reasoning\n(a+b)² is not a²+b². The exponent applies to the grouped *sum*, including cross terms.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "x³ × x² / x⁴ = x", new Exercise(ExerciseKind.Numeric, "Practice: Exponent rules with positive and negative powers", "Evaluate (2³ × 2²) / 2⁴.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 2d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Multiply powers with the same base by adding exponents: 2³×2²=2⁵. Divide by 2⁴: 2^(5−4)=2¹=2."), null, docs),
            new("algebra1-scientific-notation", "Exponents and growth", 17, "Scientific notation and powers of ten", "Sensor times and satellite distances can span many orders of magnitude.", "Scientific notation expresses a nonzero number as a number with magnitude from 1 to under 10 times 10 to an integer power.", "## What it means\nScientific notation expresses a nonzero number as a number with magnitude from 1 to under 10 times 10 to an integer power.\n\n## Where you'll use it\nSensor times and satellite distances can span many orders of magnitude. 0.000004 m is 4×10⁻⁶ m, easier to compare than a string of zeros.\n\n## Work through an example\n1. Convert 58,000,000 to scientific notation. 2. Move the decimal seven places left to get 5.8. 3. Compensate with ×10⁷. 4. Check 5.8×10⁷=58,000,000.\n\n## Read the math\n58,000,000 = 5.8×10⁷\n\n## Check the reasoning\nThe power of ten tracks moved places, not number of significant digits; small values use negative exponents.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "58,000,000 = 5.8×10⁷", new Exercise(ExerciseKind.Numeric, "Practice: Scientific notation and powers of ten", "How many meters is 3×10⁻³ m as a decimal?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 0.003d, Tolerance: 0.001d, Unit: "m", WorkedSolution: "10⁻³ = 1/1000 = 0.001. Multiply by 3: 3×0.001 = 0.003 m."), null, docs),
            new("algebra1-exponential-functions", "Exponents and growth", 18, "Exponential growth and decay", "A $100 savings balance growing by 5% yearly follows A(t)=100(1.05)^t, where t is years and A is dollars.", "Exponential changes multiply by the same factor per equal interval, rather than adding a fixed amount.", "## What it means\nExponential changes multiply by the same factor per equal interval, rather than adding a fixed amount.\n\n## Where you'll use it\nA $100 savings balance growing by 5% yearly follows A(t)=100(1.05)^t, where t is years and A is dollars.\n\n## Work through an example\n1. Start with 200 cells doubling each hour. 2. Model N(t)=200×2ᵗ. 3. At t=3, N=200×8=1,600 cells. 4. Compare linear model 200+200×3=800: multiplying is different from adding.\n\n## Read the math\nN(t)=200×2^t ; N(3)=1600\n\n## Check the reasoning\nRepeated percentage change is exponential, but a fixed dollar increase per period is linear.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "N(t)=200×2^t ; N(3)=1600", new Exercise(ExerciseKind.Numeric, "Practice: Exponential growth and decay", "A culture starts with 50 cells and doubles every hour. How many cells after 4 hours?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 800d, Tolerance: 0.001d, Unit: "cells", WorkedSolution: "Doubling four times gives 2⁴=16. Multiply the original 50 cells by 16 to get 800 cells; the count is not 50+4×2."), null, docs),
            new("algebra1-polynomial-terms", "Polynomials", 19, "Polynomial vocabulary and degree", "The area of a rectangle with sides x+2 and x+3 expands into a polynomial that describes area for different x.", "A polynomial is a sum of terms with nonnegative whole-number powers of a variable; degree is the largest exponent.", "## What it means\nA polynomial is a sum of terms with nonnegative whole-number powers of a variable; degree is the largest exponent.\n\n## Where you'll use it\nThe area of a rectangle with sides x+2 and x+3 expands into a polynomial that describes area for different x.\n\n## Work through an example\n1. Inspect 4x³−2x+7. 2. Its terms are 4x³, −2x and 7. 3. Their exponents are 3,1,0, so degree is 3. 4. Coefficients are 4 and −2; constant is 7.\n\n## Read the math\n4x³−2x+7 ; degree=3\n\n## Check the reasoning\nx⁻¹ and √x are not polynomial terms because their powers are not nonnegative integers.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "4x³−2x+7 ; degree=3", new Exercise(ExerciseKind.Numeric, "Practice: Polynomial vocabulary and degree", "Evaluate x²+2x+1 at x=3.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 16d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Insert x=3 into x²+2x+1. Compute 3²=9 and 2×3=6; add 9+6+1 = 16."), null, docs),
            new("algebra1-add-polynomials", "Polynomials", 20, "Add and subtract polynomials", "Inventory forecasts may combine two expressions for production; polynomial addition handles the result without choosing a specific week.", "Align like powers and combine matching coefficients; distribute minus signs across a subtracted polynomial.", "## What it means\nAlign like powers and combine matching coefficients; distribute minus signs across a subtracted polynomial.\n\n## Where you'll use it\nInventory forecasts may combine two expressions for production; polynomial addition handles the result without choosing a specific week.\n\n## Work through an example\n1. Add (2x²+3x+1)+(x²−x+5). 2. Group x²: 2+1=3. 3. Group x: 3−1=2. 4. Constants: 1+5=6. Result 3x²+2x+6.\n\n## Read the math\n(2x²+3x+1)+(x²−x+5)=3x²+2x+6\n\n## Check the reasoning\nSubtracting a polynomial flips the sign of *every* term in its parentheses.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "(2x²+3x+1)+(x²−x+5)=3x²+2x+6", new Exercise(ExerciseKind.Numeric, "Practice: Add and subtract polynomials", "Evaluate (2x²+3)+(x²−1) at x=2.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 14d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Combine like terms (2x²+3)+(x²−1) = 3x²+2. At x=2, square to get 4; 3×4+2=14."), null, docs),
            new("algebra1-multiply-polynomials", "Polynomials", 21, "Multiply polynomials and special products", "A rectangular garden with sides x+2 and x+3 has area (x+2)(x+3), which depends on x.", "Distribute every term in one polynomial across every term in the other, then combine like powers.", "## What it means\nDistribute every term in one polynomial across every term in the other, then combine like powers.\n\n## Where you'll use it\nA rectangular garden with sides x+2 and x+3 has area (x+2)(x+3), which depends on x.\n\n## Work through an example\n1. Expand (x+2)(x+3). 2. Distribute x: x²+3x. 3. Distribute 2: 2x+6. 4. Combine like terms: x²+5x+6. 5. At x=2, area 4×5=20 and polynomial 4+10+6=20.\n\n## Read the math\n(x+2)(x+3)=x²+5x+6\n\n## Check the reasoning\n(a+b)² equals a²+2ab+b², not a²+b².\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "(x+2)(x+3)=x²+5x+6", new Exercise(ExerciseKind.Numeric, "Practice: Multiply polynomials and special products", "A rectangle has sides x+4 and x+2. Find area when x=3.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 35d, Tolerance: 0.001d, Unit: "units²", WorkedSolution: "At x=3 the side lengths are x+4=7 and x+2=5. The area is 7×5=35 square units. Expanding gives x²+6x+8, and substituting 3 also gives 9+18+8=35."), null, docs),
            new("algebra1-greatest-common-factor", "Factoring", 22, "Factor out a greatest common factor", "A set of items sold in bundles may have cost 6x+12; factoring 6(x+2) exposes the shared bundle size.", "Factoring reverses multiplication by expressing a polynomial as a product of simpler pieces.", "## What it means\nFactoring reverses multiplication by expressing a polynomial as a product of simpler pieces.\n\n## Where you'll use it\nA set of items sold in bundles may have cost 6x+12; factoring 6(x+2) exposes the shared bundle size.\n\n## Work through an example\n1. Factor 12x²+18x. 2. Both terms share numeric factor 6 and variable x. 3. Remove 6x: 6x(2x+3). 4. Verify 6x×2x=12x² and 6x×3=18x.\n\n## Read the math\n12x²+18x = 6x(2x+3)\n\n## Check the reasoning\nA factored expression is not a solved equation. Do not set each factor equal to zero unless the *entire product equals zero*.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "12x²+18x = 6x(2x+3)", new Exercise(ExerciseKind.Numeric, "Practice: Factor out a greatest common factor", "Factor 6x + 18 as 6(x + c). What is c?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "6x+18=6(x+3) because 18/6=3. Therefore c=3. Expand 6x+6×3 to check."), null, docs),
            new("algebra1-factor-trinomials", "Factoring", 23, "Factor quadratic trinomials", "A rectangle of area x²+7x+12 can have side lengths (x+3) and (x+4), giving geometric meaning to factors.", "For x²+bx+c, find two numbers whose sum is b and product is c.", "## What it means\nFor x²+bx+c, find two numbers whose sum is b and product is c.\n\n## Where you'll use it\nA rectangle of area x²+7x+12 can have side lengths (x+3) and (x+4), giving geometric meaning to factors.\n\n## Work through an example\n1. Factor x²+5x+6. 2. Find two numbers that multiply to 6 and add to 5: 2 and 3. 3. Rewrite as (x+2)(x+3). 4. Expand to check: x²+5x+6.\n\n## Read the math\nx²+5x+6 = (x+2)(x+3)\n\n## Check the reasoning\nA sign mistake is easy when c is negative; test both the sum and the product, then expand.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "x²+5x+6 = (x+2)(x+3)", new Exercise(ExerciseKind.Numeric, "Practice: Factor quadratic trinomials", "A trinomial x²+7x+12 factors as (x+3)(x+c). Find c.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 4d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "The factors of x²+7x+12 are (x+3)(x+4), because 3×4=12 and 3+4=7. Thus c=4."), null, docs),
            new("algebra1-difference-of-squares", "Factoring", 24, "Difference of squares and zero-product rule", "A square frame's large square minus small square has area L²−l², so factoring describes its usable border.", "a²−b² factors into (a−b)(a+b); if a product is zero, at least one factor must be zero.", "## What it means\na²−b² factors into (a−b)(a+b); if a product is zero, at least one factor must be zero.\n\n## Where you'll use it\nA square frame's large square minus small square has area L²−l², so factoring describes its usable border.\n\n## Work through an example\n1. Solve x²−25=0. 2. Recognize difference of squares: (x−5)(x+5)=0. 3. Zero-product rule gives x=5 or x=−5. 4. Both square to 25.\n\n## Read the math\nx²−25=(x−5)(x+5) ⇒ x=±5\n\n## Check the reasoning\nA sum of squares x²+25 does not factor into (x+5)(x−5) over real numbers.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "x²−25=(x−5)(x+5) ⇒ x=±5", new Exercise(ExerciseKind.Numeric, "Practice: Difference of squares and zero-product rule", "For x²−49=0, what is the positive root?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 7d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Set x²−49=0, so x²=49. The solutions are +7 and −7 because both square to 49; the positive root requested is 7."), null, docs),
            new("algebra1-parabola-graphs", "Quadratic functions", 25, "Graph quadratics, vertex, and intercepts", "A ball thrown upward follows an approximately quadratic height-time curve over a short interval when air resistance is ignored.", "A quadratic y=ax²+bx+c graphs as a parabola; its vertex is a turning point.", "## What it means\nA quadratic y=ax²+bx+c graphs as a parabola; its vertex is a turning point.\n\n## Where you'll use it\nA ball thrown upward follows an approximately quadratic height-time curve over a short interval when air resistance is ignored.\n\n## Work through an example\n1. Examine y=(x−2)²−3. 2. The squared quantity is smallest at x=2. 3. The vertex is (2,−3); it opens upward because coefficient is positive. 4. At x=0, y=4−3=1, the y-intercept.\n\n## Read the math\ny=(x−2)²−3 ; vertex (2,−3)\n\n## Check the reasoning\nThe vertex and x-intercepts are different; a quadratic may have zero, one or two real x-intercepts.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "y=(x−2)²−3 ; vertex (2,−3)", new Exercise(ExerciseKind.Numeric, "Practice: Graph quadratics, vertex, and intercepts", "Evaluate y=(x−2)²−3 at x=2.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "At x=2, the squared term (x−2)² becomes 0²=0. Subtract 3, so y=−3. This is the vertex's minimum value."), null, docs),
            new("algebra1-complete-square", "Quadratic functions", 26, "Completing the square", "Optimizing a garden with a fixed amount of fencing often leads to a quadratic; the vertex gives the best dimension.", "Rewriting x²+bx as a perfect square minus a correction reveals the vertex.", "## What it means\nRewriting x²+bx as a perfect square minus a correction reveals the vertex.\n\n## Where you'll use it\nOptimizing a garden with a fixed amount of fencing often leads to a quadratic; the vertex gives the best dimension.\n\n## Work through an example\n1. Rewrite x²+6x+5. 2. Half the x coefficient: 6/2=3; square it: 9. 3. Add and subtract 9: (x²+6x+9)−9+5. 4. Obtain (x+3)²−4. 5. Vertex is (−3,−4).\n\n## Read the math\nx²+6x+5=(x+3)²−4\n\n## Check the reasoning\nAdding the square to one side of an equation requires balancing the other side; rewriting an expression means adding and subtracting the same amount.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "x²+6x+5=(x+3)²−4", new Exercise(ExerciseKind.Numeric, "Practice: Completing the square", "For y=x²+4x+1, what is its minimum y-value?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Complete the square: x²+4x+1 = (x+2)²−4+1 = (x+2)²−3. The square cannot be negative, so the minimum y is −3 at x=−2."), null, docs),
            new("algebra1-quadratic-formula", "Quadratic functions", 27, "Solve quadratic equations by formula and discriminant", "In engineering and physics, setting a quadratic model equal to a target can determine a time or dimension.", "The quadratic formula finds roots of ax²+bx+c=0 (a≠0) even when factoring is difficult.", "## What it means\nThe quadratic formula finds roots of ax²+bx+c=0 (a≠0) even when factoring is difficult.\n\n## Where you'll use it\nIn engineering and physics, setting a quadratic model equal to a target can determine a time or dimension.\n\n## Work through an example\n1. Solve x²−3x−4=0. 2. Here a=1,b=−3,c=−4. 3. Discriminant b²−4ac=9+16=25. 4. x=[3±√25]/2 gives x=4 or x=−1. 5. Check 4²−3×4−4=0 and (−1)²+3−4=0.\n\n## Read the math\nx = (−b ± √(b²−4ac))/(2a) ; D=b²−4ac\n\n## Check the reasoning\nThe discriminant below zero means no *real* roots, not 'zero roots' in the complex-number system.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "x = (−b ± √(b²−4ac))/(2a) ; D=b²−4ac", new Exercise(ExerciseKind.Numeric, "Practice: Solve quadratic equations by formula and discriminant", "Solve x²−5x+6=0. Enter the larger root.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 3d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "Factor x²−5x+6 = (x−2)(x−3). The roots are 2 and 3. The larger one is 3. Check 3²−5×3+6=0."), null, docs),
            new("algebra1-function-notation", "Functions", 28, "Functions, inputs, outputs, domain, and range", "The cost of an order is a function of quantity: C(q)=8+3q.", "A function assigns each allowed input exactly one output; domain lists valid inputs and range lists outputs.", "## What it means\nA function assigns each allowed input exactly one output; domain lists valid inputs and range lists outputs.\n\n## Where you'll use it\nThe cost of an order is a function of quantity: C(q)=8+3q. A whole-number quantity q cannot be −2 or 1.5 physical items.\n\n## Work through an example\n1. Define f(x)=2x−5. 2. Function notation f(4) means substitute x=4. 3. Evaluate 8−5=3. 4. For this rule over real x, domain and range are all real numbers.\n\n## Read the math\nf(x)=2x−5 ; f(4)=3\n\n## Check the reasoning\nf(x) is not f multiplied by x; it names the output for input x. Some real-world domains are restricted by context.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "f(x)=2x−5 ; f(4)=3", new Exercise(ExerciseKind.Numeric, "Practice: Functions, inputs, outputs, domain, and range", "For f(x)=3x−7, find f(2).", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -1d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "f(2) means substitute x=2 in 3x−7. Multiply 3×2=6; subtract 7 to get −1."), null, docs),
            new("algebra1-function-transformations", "Functions", 29, "Transform a graph using shifts and reflections", "Moving a parabola's vertex is useful when placing a modeled arch above a walkway or shifting a game object's motion path.", "Replacing x by x−h shifts a graph right h; adding k to output shifts it up k.", "## What it means\nReplacing x by x−h shifts a graph right h; adding k to output shifts it up k.\n\n## Where you'll use it\nMoving a parabola's vertex is useful when placing a modeled arch above a walkway or shifting a game object's motion path.\n\n## Work through an example\n1. Start with f(x)=x², vertex (0,0). 2. For g(x)=(x−3)²+2, subtracting 3 inside shifts right 3. 3. Adding 2 shifts up 2. 4. Vertex becomes (3,2).\n\n## Read the math\nf(x)=x² → g(x)=(x−3)²+2\n\n## Check the reasoning\nInside the function the horizontal direction looks reversed: x−3 moves right, not left.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "f(x)=x² → g(x)=(x−3)²+2", new Exercise(ExerciseKind.Numeric, "Practice: Transform a graph using shifts and reflections", "For g(x)=(x+2)²−5, what is the vertex's y-coordinate?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: -5d, Tolerance: 0.001d, Unit: "units", WorkedSolution: "For g(x)=(x+2)²−5 the squared term is zero when x=−2. The vertex is (−2,−5), so its y-coordinate is −5."), null, docs),
            new("algebra1-piecewise-functions", "Functions", 30, "Piecewise rules, absolute value, and boundaries", "A service charges $10 for up to two hours, then $4 for every additional hour.", "A piecewise function uses different formulas for different inputs; boundary inclusion matters.", "## What it means\nA piecewise function uses different formulas for different inputs; boundary inclusion matters.\n\n## Where you'll use it\nA service charges $10 for up to two hours, then $4 for every additional hour. Its cost changes rule after two hours.\n\n## Work through an example\n1. Define C(t)=10 for 0≤t≤2, and C(t)=10+4(t−2) for t>2. 2. For 1.5 hours use first rule: $10. 3. For 4 hours use second: 10+4×2=$18. 4. At exactly 2 hours use the included first range; both rules meet at $10.\n\n## Read the math\nC(t)=10 (t≤2); C(t)=10+4(t−2) (t>2)\n\n## Check the reasoning\nDo not apply both formulas or ignore which side owns a boundary. Absolute value |x| is a piecewise distance rule: x for x≥0 and −x for x<0.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "C(t)=10 (t≤2); C(t)=10+4(t−2) (t>2)", new Exercise(ExerciseKind.Numeric, "Practice: Piecewise rules, absolute value, and boundaries", "A service costs $10 up to 2 hours, then $4 for each extra hour. What does 5 hours cost?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 22d, Tolerance: 0.001d, Unit: "USD", WorkedSolution: "The first two hours cost $10 total. Five hours include three extra hours, each $4: 10+4(5−2)=10+12=$22."), null, docs),
            new("algebra1-choose-math-model", "Applications and capstone", 31, "Decide which model fits a situation", "A car at constant speed is proportional distance vs time from zero; a taxi with an initial fee is linear but not proportional; doubling popu", "Use how a quantity changes to choose linear, proportional, quadratic, or exponential models.", "## What it means\nUse how a quantity changes to choose linear, proportional, quadratic, or exponential models.\n\n## Where you'll use it\nA car at constant speed is proportional distance vs time from zero; a taxi with an initial fee is linear but not proportional; doubling populations are exponential.\n\n## Work through an example\n1. An investment grows from $100 to $110 to $121 over equal years. 2. Each step multiplies by 1.1, so model is exponential: A(t)=100(1.1)ᵗ. 3. At t=3, A=100×1.331=$133.10. 4. If it had added $10 each year it would be linear instead.\n\n## Read the math\nA(t)=100(1.1)^t ; A(3)=$133.10\n\n## Check the reasoning\nA pattern of three points alone may support many formulas; context and assumptions matter. State the assumed constant rate or factor.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "A(t)=100(1.1)^t ; A(3)=$133.10", new Exercise(ExerciseKind.Numeric, "Practice: Decide which model fits a situation", "An initial $40 balance doubles every week. How much after 3 weeks?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 320d, Tolerance: 0.001d, Unit: "USD", WorkedSolution: "A $40 balance doubles each week. After three weeks it is 40×2³=40×8=$320. A constant additive increase is not the model here."), null, docs),
            new("algebra1-model-from-data", "Applications and capstone", 32, "Fit lines to data and inspect assumptions", "A student's measured practice time and quiz score may show an upward trend but other factors still affect scores.", "A trend line summarizes approximate data, not a perfect law; compare predictions with observations.", "## What it means\nA trend line summarizes approximate data, not a perfect law; compare predictions with observations.\n\n## Where you'll use it\nA student's measured practice time and quiz score may show an upward trend but other factors still affect scores.\n\n## Work through an example\n1. A machine output is 7, 12, 17 units at times 0,1,2 hours. 2. Each step adds 5, so slope m=5 units/hour. 3. Start value is b=7. 4. Model y=5t+7, predict t=3 gives 22. 5. Check whether measured values justify extrapolating further.\n\n## Read the math\n(t,y): (0,7),(1,12),(2,17) ⇒ y=5t+7\n\n## Check the reasoning\nCorrelation is not causation; a straight trend outside measured data may fail.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "(t,y): (0,7),(1,12),(2,17) ⇒ y=5t+7", new Exercise(ExerciseKind.Numeric, "Practice: Fit lines to data and inspect assumptions", "A tank measures 4 L at minute 0 and 16 L at minute 3 while filling steadily. Predict its volume at minute 5.", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 24d, Tolerance: 0.001d, Unit: "L", WorkedSolution: "Steady filling: (16−4) L over 3 min = 4 L/min. Model volume V(t)=4+4t. At t=5, V=4+20=24 L."), null, docs),
            new("algebra1-algebra-capstone", "Applications and capstone", 33, "Capstone: compare two real pricing plans", "A small organization compares two printing services.", "Combine modeling, equations, inequalities, units, and checks to make a justified decision.", "## What it means\nCombine modeling, equations, inequalities, units, and checks to make a justified decision.\n\n## Where you'll use it\nA small organization compares two printing services. Plan A costs a $30 setup plus $0.12 per page; Plan B has no setup and costs $0.20 per page.\n\n## Work through an example\n1. Define p as pages. A(p)=30+0.12p; B(p)=0.20p. 2. At break-even set 30+0.12p=0.20p. 3. Subtract 0.12p: 30=0.08p. Divide: p=375. 4. Check both plans cost $75 at 375 pages. 5. At p=500, A=$90 and B=$100, so A wins after 375 pages.\n\n## Read the math\nA(p)=30+0.12p ; B(p)=0.20p ; break-even p=375\n\n## Check the reasoning\nThe cheaper choice depends on quantity. The equation alone yields a boundary, not which side is preferred; test one quantity on each side.\n\n## Try it\nApply the same reasoning to the practice question. The module checkpoint comes after instruction and guided practice for all lessons in this module.", "A(p)=30+0.12p ; B(p)=0.20p ; break-even p=375", new Exercise(ExerciseKind.Numeric, "Practice: Capstone: compare two real pricing plans", "Plan A costs $24 plus $0.10 per page and plan B costs $0.16 per page. At what page count do they cost the same?", ["Identify the quantities and relevant operations", "Calculate the answer and keep its sign and units", "Verify in the original situation"], null, null, [], "Follow the worked example; use inverse operations or substitution to check.", ["Uses the correct relationship", "Keeps the sign and units"], ExpectedNumeric: 400d, Tolerance: 0.001d, Unit: "pages", WorkedSolution: "Plan A: 24+0.10p. Plan B: 0.16p. Set equal: 24+0.10p=0.16p. Subtract 0.10p: 24=0.06p, so p=24/0.06=400 pages. Check both cost $64."), null, docs),
        };
        return NormalizeLessons(lessons);
